//! Tests for src/draw.rs (3 tests). Do not edit this file.
//!
//! Run just these with: cargo test draw::

use super::*;

#[test]
fn to_coord_of_zero_is_zero() {
    assert_eq!(to_coord(0), 0.0);
}

#[test]
fn to_coord_multiplies_by_block_size() {
    assert_eq!(to_coord(1), BLOCK_SIZE);
    assert_eq!(to_coord(4), 100.0);
    assert_eq!(to_coord(-2), -50.0);
}

#[test]
fn to_coord_u32_matches_to_coord() {
    assert_eq!(to_coord_u32(0), 0);
    assert_eq!(to_coord_u32(1), 25);
    assert_eq!(to_coord_u32(30), 750);
}
